//! Unit tests for the OAuth handoff policy.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::cell::Cell;

use super::*;
use crate::{Error, Result};

#[test]
fn recognizes_meta_toolkits_regardless_of_casing_or_padding() {
    for toolkit in ["instagram", "Instagram", " FACEBOOK ", "facebook"] {
        assert!(is_meta_oauth_toolkit(toolkit), "{toolkit:?} is Meta-hosted");
    }
}

#[test]
fn does_not_treat_other_toolkits_as_meta_hosted() {
    for toolkit in ["gmail", "slack", "notion", ""] {
        assert!(!is_meta_oauth_toolkit(toolkit), "{toolkit:?} is not Meta");
    }
}

#[test]
fn treats_pending_initiated_and_initializing_as_in_flight() {
    for status in ["PENDING", "initiated", " Initializing "] {
        assert!(is_inflight_oauth_status(status), "{status:?} is in flight");
    }
}

#[test]
fn does_not_treat_a_finished_status_as_in_flight() {
    for status in ["ACTIVE", "FAILED", "EXPIRED", ""] {
        assert!(!is_inflight_oauth_status(status));
    }
}

#[test]
fn clears_in_flight_and_failed_rows_but_never_an_active_one() {
    for status in [
        "PENDING",
        "INITIATED",
        "INITIALIZING",
        "FAILED",
        "ERROR",
        "EXPIRED",
    ] {
        assert!(is_clearable_oauth_status(status), "{status:?} is clearable");
    }
    for status in ["ACTIVE", "CONNECTED", ""] {
        assert!(
            !is_clearable_oauth_status(status),
            "{status:?} must be kept"
        );
    }
}

#[test]
fn detects_every_observed_spelling_of_a_rate_limit() {
    for message in [
        "HTTP 429 from upstream",
        "Too Many Requests",
        "upstream rate limit exceeded",
        "error: rate_limit_hit",
        "RateLimited",
    ] {
        assert!(is_authorize_rate_limited(message), "{message:?}");
    }
}

#[test]
fn does_not_mistake_an_ordinary_failure_for_a_rate_limit() {
    for message in ["invalid toolkit", "403 forbidden", "connection reset"] {
        assert!(!is_authorize_rate_limited(message), "{message:?}");
    }
}

#[test]
fn gives_instagram_and_facebook_their_own_account_hints() {
    let instagram = meta_oauth_rate_limit_message("instagram");
    assert!(instagram.contains("Business or Creator"));

    let facebook = meta_oauth_rate_limit_message("facebook");
    assert!(facebook.contains("Page or Business Manager"));

    // A toolkit with no known cause gets the backoff advice and nothing made up.
    let other = meta_oauth_rate_limit_message("gmail");
    assert!(other.contains("Wait a few"));
    assert!(!other.contains("Business"));
}

#[test]
fn wraps_only_a_meta_rate_limit() {
    let rate_limited = || Error::Authorize {
        toolkit: "instagram".into(),
        message: "HTTP 429 too many requests".into(),
    };

    let wrapped = wrap_authorize_rate_limit_error("instagram", rate_limited());
    assert!(matches!(wrapped, Error::OauthRateLimited { .. }));
    assert!(wrapped.to_string().contains("Business or Creator"));

    // Same failure, non-Meta toolkit: the original message is more useful.
    let untouched = wrap_authorize_rate_limit_error("gmail", rate_limited());
    assert!(matches!(untouched, Error::Authorize { .. }));

    // Meta toolkit, but not a rate limit.
    let other = wrap_authorize_rate_limit_error(
        "facebook",
        Error::Authorize {
            toolkit: "facebook".into(),
            message: "invalid scope".into(),
        },
    );
    assert!(matches!(other, Error::Authorize { .. }));
}

#[tokio::test(start_paused = true)]
async fn returns_the_first_success_without_retrying() {
    let calls = Cell::new(0u32);
    let result = authorize_with_rate_limit_retry(|| {
        calls.set(calls.get() + 1);
        async { Ok::<_, Error>("connect-url") }
    })
    .await;

    assert_eq!(result.unwrap(), "connect-url");
    assert_eq!(calls.get(), 1);
}

#[tokio::test(start_paused = true)]
async fn retries_a_rate_limit_and_succeeds_on_a_later_attempt() {
    let calls = Cell::new(0u32);
    let result = authorize_with_rate_limit_retry(|| {
        calls.set(calls.get() + 1);
        let attempt = calls.get();
        async move {
            if attempt < 3 {
                Err(Error::Authorize {
                    toolkit: "instagram".into(),
                    message: "429 too many requests".into(),
                })
            } else {
                Ok("connect-url")
            }
        }
    })
    .await;

    assert_eq!(result.unwrap(), "connect-url");
    assert_eq!(calls.get(), 3);
}

#[tokio::test(start_paused = true)]
async fn gives_up_after_the_attempt_limit() {
    let calls = Cell::new(0u32);
    let result: Result<&str> = authorize_with_rate_limit_retry(|| {
        calls.set(calls.get() + 1);
        async {
            Err(Error::Authorize {
                toolkit: "instagram".into(),
                message: "429 too many requests".into(),
            })
        }
    })
    .await;

    assert!(result.is_err());
    assert_eq!(calls.get(), AUTHORIZE_RATE_LIMIT_MAX_ATTEMPTS);
}

#[tokio::test(start_paused = true)]
async fn does_not_retry_a_failure_that_is_not_a_rate_limit() {
    let calls = Cell::new(0u32);
    let result: Result<&str> = authorize_with_rate_limit_retry(|| {
        calls.set(calls.get() + 1);
        async {
            Err(Error::Authorize {
                toolkit: "gmail".into(),
                message: "invalid toolkit".into(),
            })
        }
    })
    .await;

    assert!(result.is_err());
    assert_eq!(calls.get(), 1, "a permanent failure must not be retried");
}

#[tokio::test(start_paused = true)]
async fn a_rate_limit_that_outlives_every_attempt_becomes_guidance() {
    // The two halves compose: the retry gives up, and wrapping turns the raw
    // upstream text into something the user can act on.
    let result: Result<&str> = authorize_with_rate_limit_retry(|| async {
        Err(Error::Authorize {
            toolkit: "instagram".into(),
            message: "429 too many requests".into(),
        })
    })
    .await;

    let wrapped = wrap_authorize_rate_limit_error("instagram", result.unwrap_err());
    assert!(matches!(wrapped, Error::OauthRateLimited { .. }));
    assert!(wrapped.to_string().contains("Business or Creator"));
}

#[tokio::test(start_paused = true)]
async fn the_backoff_grows_between_attempts() {
    // Doubling matters: a fixed short delay retries inside the same rate-limit
    // window and burns all three attempts for nothing.
    let started = tokio::time::Instant::now();
    let _: Result<&str> = authorize_with_rate_limit_retry(|| async {
        Err(Error::Authorize {
            toolkit: "instagram".into(),
            message: "429".into(),
        })
    })
    .await;

    // Two sleeps before the third attempt gives up: 5s then 10s.
    assert!(started.elapsed() >= std::time::Duration::from_secs(15));
}

# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Backing off when the OAuth host rate-limits an authorize call.

use std::time::Duration;

use super::status::{
    is_authorize_rate_limited, is_meta_oauth_toolkit, meta_oauth_rate_limit_message,
};
use crate::{Error, Result};

/// How many times an authorize call is attempted before the rate limit is
/// reported to the caller.
pub const AUTHORIZE_RATE_LIMIT_MAX_ATTEMPTS: u32 = 3;

const AUTHORIZE_RATE_LIMIT_INITIAL_BACKOFF: Duration = Duration::from_secs(5);
const AUTHORIZE_RATE_LIMIT_MAX_BACKOFF: Duration = Duration::from_secs(60);

/// Replace a Meta rate-limit failure with guidance the user can act on.
///
/// Non-Meta toolkits and non-rate-limit failures pass through untouched: the
/// original message is more useful than a generic one, and only Meta's flows
/// have the account-type causes the guidance describes.
#[must_use]
pub fn wrap_authorize_rate_limit_error(toolkit: &str, error: Error) -> Error {
    let rendered = error.to_string();
    if is_meta_oauth_toolkit(toolkit) && is_authorize_rate_limited(&rendered) {
        Error::OauthRateLimited {
            toolkit: toolkit.trim().to_string(),
            message: meta_oauth_rate_limit_message(toolkit),
        }
    } else {
        error
    }
}

/// Run `attempt` until it succeeds, is rejected for a reason other than rate
/// limiting, or [`AUTHORIZE_RATE_LIMIT_MAX_ATTEMPTS`] is reached.
///
/// The backoff doubles from five seconds and is capped at a minute. It is
/// generic over the attempt rather than taking a client so the policy can be
/// tested — and reused by direct mode — without an HTTP round trip.
///
/// # Errors
///
/// Returns the last failure `attempt` produced. A rate limit that outlives
/// every attempt is returned as it arrived; call
/// [`wrap_authorize_rate_limit_error`] to turn it into user-facing guidance.
pub async fn authorize_with_rate_limit_retry<T, F, Fut>(mut attempt: F) -> Result<T>
where
    F: FnMut() -> Fut,
    Fut: std::future::Future<Output = Result<T>>,
{
    let mut delay = AUTHORIZE_RATE_LIMIT_INITIAL_BACKOFF;

    // Every attempt but the last. Written this way rather than as a loop over
    // all of them so there is no unreachable "ran out of attempts" arm at the
    // end: the final attempt below is the one that reports.
    for attempt_number in 1..AUTHORIZE_RATE_LIMIT_MAX_ATTEMPTS {
        match attempt().await {
            Ok(value) => return Ok(value),
            Err(error) => {
                if !is_authorize_rate_limited(&error.to_string()) {
                    return Err(error);
                }
                let sleep_secs = delay.as_secs();
                tracing::warn!(
                    attempt = attempt_number,
                    sleep_secs,
                    "[connectors][oauth] authorize rate-limited; backing off"
                );
                tokio::time::sleep(delay).await;
                delay = (delay * 2).min(AUTHORIZE_RATE_LIMIT_MAX_BACKOFF);
            }
        }
    }

    // The last attempt, reported whatever it produces.
    attempt().await
}

//! Integration tests for the public crate surface.
//!
//! These tests link against the crate as a downstream consumer would: they can
//! only use what `src/lib.rs` re-exports. Treat them as the regression suite
//! for the crate's public contract — if a change breaks a test here, it is a
//! breaking change for users.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyconnectors::{
    ComposioConnection, Error, client::Transport, names, oauth, tinyconnectors_bus,
};

#[test]
fn the_payload_vocabulary_is_the_contract_crate_s_own_types() {
    // Not a tautology: if this crate ever redefined the payloads rather than
    // re-exporting them, a host linking `tinyconnectors-bus` would be passing
    // structural twins that need a conversion nothing checks.
    fn accepts(_: tinyconnectors_bus::ComposioConnection) {}

    let connection: ComposioConnection = serde_json::from_value(serde_json::json!({
        "id": "c1", "toolkit": "gmail", "status": "ACTIVE"
    }))
    .unwrap();
    accepts(connection);
}

#[test]
fn the_bus_identity_is_available_to_consumers() {
    assert_eq!(names::INTERFACE, "ai.tinyhumans.connectors.Composio");
    assert_eq!(names::OBJECT_PATH, "/ai/tinyhumans/connectors/Composio");
    // Not a count: a count passes through a member being swapped for another,
    // and the point of the table is which members a host may call.
    assert!(names::METHODS.contains(&names::methods::AUTHORIZE));
    assert!(names::METHODS.contains(&names::methods::EXECUTE));
    assert!(names::METHODS.contains(&names::methods::LIST_TRIGGER_HISTORY));
}

#[test]
fn the_oauth_policy_is_available_to_consumers() {
    assert!(oauth::is_meta_oauth_toolkit("instagram"));
    assert!(oauth::is_clearable_oauth_status("PENDING"));
    assert!(!oauth::is_clearable_oauth_status("ACTIVE"));
}

#[test]
fn errors_are_available_to_consumers() {
    let error = Error::Authorize {
        toolkit: "gmail".into(),
        message: "invalid scope".into(),
    };
    assert_eq!(
        error.to_string(),
        "authorize failed for gmail: invalid scope"
    );
}

#[test]
fn the_transport_seam_is_implementable_from_outside_the_crate() {
    // The whole point of the seam: a host supplies its own auth. If `Transport`
    // stopped being nameable and object-safe from outside, this stops building.
    fn assert_object_safe(_: &dyn Transport) {}
    let _ = assert_object_safe;
}

/// The module must load with no configuration at all.
///
/// This is what the release gate does — and what any host loading modules
/// generically does. It was found by that gate failing: the module used to
/// refuse an empty configuration, which meant it could not be verified after
/// publication and could not answer the members that need no credential.
#[tokio::test]
async fn the_built_module_loads_with_an_empty_configuration() {
    use tinybus::broker::Broker;
    use tinybus::module::ModuleHost;
    use tinybus::transport::memory::MemoryBus;

    let module = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../target/debug")
        .join(format!(
            "{}tinyconnectors{}",
            std::env::consts::DLL_PREFIX,
            std::env::consts::DLL_SUFFIX
        ));
    if !module.exists() {
        // `cargo test` does not guarantee the cdylib is built; the example and
        // the release workflow both cover this against a real artifact.
        return;
    }

    let bus = MemoryBus::new();
    let broker = Broker::new();
    let task = broker.spawn(bus.clone());
    let host = ModuleHost::new(broker);

    let info = host
        .load_file_with_config(&module, serde_json::json!({}))
        .expect("an empty configuration must load");
    assert_eq!(info.name, "tinyconnectors");
    task.abort();
}

//! Adapting the module's client to the provider action seam.

use std::sync::{Arc, PoisonError, RwLock};

use async_trait::async_trait;
use tinyconnectors_sync::{ActionRunner, Error as SyncError, Result as SyncResult};

use crate::client::ComposioClient;

/// Runs provider actions through this module's Composio client.
///
/// The client is optional because the module loads without one: a host that
/// only wants the capability members should not have to supply a credential.
/// A provider that then tries to run an action gets a named refusal rather than
/// a module that would not load at all.
///
/// It is *shared* rather than owned because the route can be replaced while the
/// module runs — a user signs in after a lazily-loaded module was already up.
/// A runner holding its own copy would keep running syncs against the
/// credential the module happened to start with, which after a sign-out is one
/// that answers 401 to everything.
#[derive(Debug, Clone)]
pub struct ClientActions {
    client: Arc<RwLock<Option<ComposioClient>>>,
}

impl ClientActions {
    /// Build a runner sharing the module's current client.
    #[must_use]
    pub fn new(client: Arc<RwLock<Option<ComposioClient>>>) -> Self {
        Self { client }
    }
}

/// What to report when a provider refuses an action.
///
/// The execute pipeline formats a message for every failed response, so the
/// fallback is not expected — but "the provider said no and would not say why"
/// is still more useful to whoever reads the sync log than an empty string.
pub(crate) fn refusal_message(error: Option<String>) -> String {
    error
        .map(|error| error.trim().to_string())
        .filter(|error| !error.is_empty())
        .unwrap_or_else(|| "the provider reported failure".to_string())
}

#[async_trait]
impl ActionRunner for ClientActions {
    async fn run(
        &self,
        action: &str,
        arguments: serde_json::Value,
        connection_id: &str,
    ) -> SyncResult<serde_json::Value> {
        let client = self
            .client
            .read()
            .unwrap_or_else(PoisonError::into_inner)
            .clone()
            .ok_or_else(|| SyncError::Action {
                action: action.to_string(),
                message: "this module was loaded without a connector route".to_string(),
            })?;

        let response = client
            .execute(action, Some(arguments), Some(connection_id))
            .await
            .map_err(|error| SyncError::Action {
                action: action.to_string(),
                message: error.to_string(),
            })?;

        if !response.successful {
            // A refusal is an error for a provider even though `Execute`
            // reports it as a reply: a sync that treated a refused page as an
            // empty one would record "nothing new" and advance its cursor past
            // records it never read.
            return Err(SyncError::Action {
                action: action.to_string(),
                message: refusal_message(response.error),
            });
        }

        Ok(response.data)
    }
}

//! OAuth handoff policy: which statuses mean what, and how to survive Meta's
//! rate limiter.
//!
//! Linking an account is a handoff, not a call. The module asks the backend to
//! start one, gets back a hosted URL, and the user finishes it in a browser
//! minutes later — or abandons it. Everything awkward about this module follows
//! from that gap.
//!
//! # Abandoned handoffs accumulate
//!
//! Each authorize call creates a connection row immediately, in a non-active
//! state. A user who clicks Connect, hesitates, and clicks again leaves two.
//! [`is_clearable_oauth_status`] identifies the rows that a fresh handoff may
//! delete, and [`is_inflight_oauth_status`] separates "still might succeed"
//! from "already failed" within that set.
//!
//! # Meta rate-limits the accumulation
//!
//! Instagram and Facebook share one OAuth host that returns HTTP 429 when too
//! many sessions are created in a short window — which is exactly what the
//! retry-then-retry pattern above produces. Two mitigations live here:
//! clearing stale rows before starting a new handoff (the caller does this with
//! [`is_meta_oauth_toolkit`] and [`is_clearable_oauth_status`]), and backing off
//! when a 429 does arrive ([`authorize_with_rate_limit_retry`]).
//!
//! The 429 is detected by [`is_authorize_rate_limited`] against the *rendered*
//! error text rather than a status code. That is deliberate: the failure
//! reaches this module through a backend proxy that has already turned the
//! upstream response into a message, so the code is gone by the time we see it.
//!
//! # Why the guidance message is here and not in the UI
//!
//! [`meta_oauth_rate_limit_message`] returns prose, which looks out of place in
//! a policy module. A rate-limited Meta sign-in is almost always one of two
//! specific, fixable mistakes — a personal Instagram account rather than a
//! Business one, or a Facebook account without Page access — and the toolkit
//! slug is the only thing that distinguishes them. Rendering it here keeps
//! every caller telling the user the same true thing.

mod retry;
mod status;

pub use retry::{
    AUTHORIZE_RATE_LIMIT_MAX_ATTEMPTS, authorize_with_rate_limit_retry,
    wrap_authorize_rate_limit_error,
};
pub use status::{
    META_OAUTH_TOOLKITS, is_authorize_rate_limited, is_clearable_oauth_status,
    is_inflight_oauth_status, is_meta_oauth_toolkit, meta_oauth_rate_limit_message,
};

#[cfg(test)]
mod test;

//! Classifying toolkits, connection statuses, and rate-limit failures.

/// Toolkits whose OAuth flows are hosted by Meta and share its rate limits.
pub const META_OAUTH_TOOLKITS: &[&str] = &["instagram", "facebook"];

/// Whether `toolkit` uses Meta-hosted OAuth.
///
/// Compared case-insensitively after trimming, because the slug reaches this
/// function from a UI field, a config file, and a backend envelope, and only
/// one of those three is reliably normalized.
#[must_use]
pub fn is_meta_oauth_toolkit(toolkit: &str) -> bool {
    let key = toolkit.trim().to_ascii_lowercase();
    META_OAUTH_TOOLKITS.contains(&key.as_str())
}

/// Whether a connection status means a handoff is still in flight.
///
/// These rows may still become active on their own — the user could be part-way
/// through the browser flow — so nothing should treat them as failures.
#[must_use]
pub fn is_inflight_oauth_status(status: &str) -> bool {
    matches!(
        status.trim().to_ascii_uppercase().as_str(),
        "PENDING" | "INITIATED" | "INITIALIZING"
    )
}

/// Whether a non-active row is safe to delete before a fresh OAuth handoff.
///
/// This deliberately includes the in-flight statuses. Starting a new handoff is
/// the user saying "do this again", which supersedes whatever half-finished
/// attempt was open — and leaving those rows is precisely what trips Meta's
/// rate limiter.
#[must_use]
pub fn is_clearable_oauth_status(status: &str) -> bool {
    let upper = status.trim().to_ascii_uppercase();
    is_inflight_oauth_status(status) || matches!(upper.as_str(), "FAILED" | "ERROR" | "EXPIRED")
}

/// Whether a rendered authorize failure looks like upstream rate limiting.
///
/// Matched against text, not a status code: by the time a failure reaches this
/// module the backend proxy has already rendered the upstream response into a
/// message. The alternatives are all spellings observed in real failures.
#[must_use]
pub fn is_authorize_rate_limited(err: &str) -> bool {
    let lower = err.to_ascii_lowercase();
    lower.contains("429")
        || lower.contains("too many requests")
        || lower.contains("rate limit")
        || lower.contains("rate_limit")
        || lower.contains("ratelimited")
}

/// User-facing guidance when Meta OAuth is rate-limited.
///
/// The account hint is the useful half. A 429 here usually means the user is
/// retrying because the flow failed for a reason Meta reports poorly, and the
/// two common causes are account-type mistakes they can fix themselves.
#[must_use]
pub fn meta_oauth_rate_limit_message(toolkit: &str) -> String {
    let name = toolkit.trim();
    let account_hint = if name.eq_ignore_ascii_case("instagram") {
        " Use an Instagram Business or Creator account — personal accounts are not supported."
    } else if name.eq_ignore_ascii_case("facebook") {
        " Confirm the Facebook account has access to the relevant Page or Business Manager."
    } else {
        ""
    };
    format!(
        "Meta is temporarily rate-limiting {name} sign-in (HTTP 429). Wait a few \
         minutes before retrying and avoid clicking Connect repeatedly.{account_hint}"
    )
}
